@push('scripts')
<script>
(function(){var form=document.getElementById('bulk-review-form'),all=document.getElementById('select-all-pending'),boxes=Array.prototype.slice.call(document.querySelectorAll('.report-checkbox')),count=document.getElementById('bulk-review-count'),action=document.getElementById('bulk-review-action'),rejectBox=document.getElementById('bulk-reject-box'),reason=document.getElementById('bulk-review-reason');if(!form)return;function selected(){return boxes.filter(function(box){return box.checked;});}function update(){var checked=selected().length;count.textContent='已选 '+checked+' 份';all.checked=boxes.length>0&&checked===boxes.length;all.indeterminate=checked>0&&checked<boxes.length;}function requireSelection(){if(selected().length)return true;window.alert('请至少选择一条待审核报表。');return false;}all.addEventListener('change',function(){boxes.forEach(function(box){box.checked=all.checked;});update();});boxes.forEach(function(box){box.addEventListener('change',update);});document.getElementById('bulk-approve').addEventListener('click',function(){if(!requireSelection())return;if(!window.confirm('确认将选中的 '+selected().length+' 份运营报表批量审核通过？'))return;action.value='approved';reason.value='';form.submit();});document.getElementById('bulk-reject').addEventListener('click',function(){if(!requireSelection())return;rejectBox.style.display='block';reason.focus();});document.getElementById('cancel-bulk-reject').addEventListener('click',function(){rejectBox.style.display='none';reason.value='';});document.getElementById('confirm-bulk-reject').addEventListener('click',function(){if(!requireSelection())return;if(!reason.value.trim()){window.alert('请输入审核不通过原因。');reason.focus();return;}if(!window.confirm('确认将选中的 '+selected().length+' 份运营报表批量审核不通过？'))return;action.value='rejected';form.submit();});update();})();
</script>
@endpush
